// ======================================================
// Normalize LINE Message
// สำหรับ LINE Chatbot + Fuzzy Logic
// ======================================================

const src = $input.first().json || {};

// Webhook ของ n8n จะเก็บ LINE payload ไว้ใน body
const body = src.body || src;

// ดึง event แรก
const events = Array.isArray(body.events) ? body.events : [];
const event = events[0] || {};

// ------------------------------------------------------
// ข้อมูล Event
// ------------------------------------------------------

const eventType = event.type || "";
const messageType = event.message?.type || "";

const replyToken = event.replyToken || "";

const userId =
  event.source?.userId ||
  event.source?.groupId ||
  event.source?.roomId ||
  "";

// ------------------------------------------------------
// ข้อความจากผู้ใช้
// ------------------------------------------------------

let userTextRaw = "";

if (
  eventType === "message" &&
  messageType === "text"
) {
  userTextRaw = String(event.message?.text || "");
}

// ------------------------------------------------------
// Normalize Text
// ------------------------------------------------------

function normalizeText(text) {
  return String(text || "")

    // Unicode normalization
    .normalize("NFKC")

    // ลบ zero-width space
    .replace(/\u200B/g, "")

    // จัด quote ให้เป็นมาตรฐาน
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'")

    // ลดช่องว่างหลายตัวให้เหลือ 1
    .replace(/\s+/g, " ")

    // ตัดช่องว่างหัวท้าย
    .trim();
}

const userText = normalizeText(userTextRaw);

// lower-case ใช้กับคำอังกฤษ เช่น GPAX / Gen Ed
const userTextLower = userText.toLowerCase();

// ------------------------------------------------------
// Output
// ------------------------------------------------------

return [
  {
    json: {
      replyToken,
      userId,

      eventType,
      messageType,

      user_text_raw: userTextRaw,
      user_text: userText,
      user_text_lower: userTextLower,

      is_text_message:
        eventType === "message" &&
        messageType === "text",

      has_text: userText.length > 0
    }
  }
];

// ======================================================
// Code | Text Similarity
// Final Version
//
// รองรับ:
// - Exact Match
// - Specific Alias
// - General Fuzzy Match
// - Teaching Case: "เคลียด" -> 60%
// - Out of Scope -> 20% + Force FALLBACK
// ======================================================


// ======================================================
// 1. รับข้อความจาก LINE
// ======================================================

const lineData =
  $("Code | Normalize Text").first().json;

const userText =
  lineData.user_text || "";


// ======================================================
// 2. Normalize
// ======================================================

function normalizeText(text) {

  return String(text || "")
    .normalize("NFKC")
    .toLowerCase()
    .replace(/\u200B/g, "")
    .replace(/[“”"'`]/g, "")
    .replace(/[?!.,;:()[\]{}]/g, "")
    .replace(/\s+/g, " ")
    .trim();

}


function compactText(text) {

  return normalizeText(text)
    .replace(/\s+/g, "");

}


function clamp(value, min = 0, max = 1) {

  return Math.min(
    Math.max(value, min),
    max
  );

}


const normalizedUser =
  compactText(userText);


// ======================================================
// 3. Sørensen-Dice
// ======================================================

function diceSimilarity(a, b) {

  a = compactText(a);
  b = compactText(b);

  if (!a || !b) {
    return 0;
  }

  if (a === b) {
    return 1;
  }

  if (a.length < 2 || b.length < 2) {

    return a === b
      ? 1
      : 0;

  }


  const bigrams =
    new Map();


  for (
    let i = 0;
    i < a.length - 1;
    i++
  ) {

    const bg =
      a.substring(i, i + 2);

    bigrams.set(
      bg,
      (bigrams.get(bg) || 0) + 1
    );

  }


  let intersection = 0;


  for (
    let i = 0;
    i < b.length - 1;
    i++
  ) {

    const bg =
      b.substring(i, i + 2);

    const count =
      bigrams.get(bg) || 0;


    if (count > 0) {

      intersection++;

      bigrams.set(
        bg,
        count - 1
      );

    }

  }


  return (
    (2 * intersection) /
    (
      (a.length - 1) +
      (b.length - 1)
    )
  );

}


// ======================================================
// 4. Prefix Similarity
// ======================================================

function commonPrefixRatio(user, alias) {

  const a =
    compactText(user);

  const b =
    compactText(alias);


  if (!a || !b) {
    return 0;
  }


  let count = 0;

  const limit =
    Math.min(a.length, b.length);


  for (
    let i = 0;
    i < limit;
    i++
  ) {

    if (a[i] === b[i]) {

      count++;

    }
    else {

      break;

    }

  }


  return (
    count /
    Math.max(b.length, 1)
  );

}


// ======================================================
// 5. Suffix Similarity
// ======================================================

function commonSuffixRatio(user, alias) {

  const a =
    compactText(user);

  const b =
    compactText(alias);


  if (!a || !b) {
    return 0;
  }


  let count = 0;

  let i =
    a.length - 1;

  let j =
    b.length - 1;


  while (
    i >= 0 &&
    j >= 0
  ) {

    if (a[i] === b[j]) {

      count++;

      i--;
      j--;

    }
    else {

      break;

    }

  }


  return (
    count /
    Math.max(b.length, 1)
  );

}


// ======================================================
// 6. Calculate Similarity
// ======================================================

function calculateSimilarity(
  userText,
  alias
) {

  const user =
    compactText(userText);

  const target =
    compactText(alias);


  if (!user || !target) {

    return {
      score: 0,
      matchType: "EMPTY"
    };

  }


  // Exact Match
  if (user === target) {

    return {
      score: 1,
      matchType: "EXACT"
    };

  }


  // ตัวเลข 1 / 2 / 3
  if (/^\d+$/.test(target)) {

    return {
      score: 0,
      matchType: "NUMBER_NO_MATCH"
    };

  }


  const dice =
    diceSimilarity(
      user,
      target
    );


  const prefixRatio =
    commonPrefixRatio(
      user,
      target
    );


  const suffixRatio =
    commonSuffixRatio(
      user,
      target
    );


  const coverageRatio =
    Math.min(
      user.length,
      target.length
    )
    /
    Math.max(
      user.length,
      target.length
    );


  // ====================================================
  // Alias อยู่ใน User
  // ====================================================

  if (
    user.includes(target)
  ) {

    let score =
      0.84 +
      (0.14 * coverageRatio);


    if (
      user.startsWith(target)
    ) {
      score += 0.02;
    }


    if (
      user.endsWith(target)
    ) {
      score += 0.02;
    }


    return {

      score:
        clamp(
          score,
          0,
          0.98
        ),

      matchType:
        "ALIAS_IN_USER"

    };

  }


  // ====================================================
  // User อยู่ใน Alias
  // ====================================================

  if (
    target.includes(user)
  ) {

    let score =
      0.86 +
      (0.10 * coverageRatio);


    if (
      target.startsWith(user)
    ) {
      score += 0.015;
    }


    if (
      target.endsWith(user)
    ) {
      score += 0.015;
    }


    return {

      score:
        clamp(
          score,
          0,
          0.97
        ),

      matchType:
        "USER_IN_ALIAS"

    };

  }


  // ====================================================
  // Composite Near Phrase
  // ====================================================

  if (
    dice >= 0.60 &&
    prefixRatio >= 0.30 &&
    suffixRatio >= 0.30
  ) {

    let score =
      0.80 +
      (0.12 * dice) +
      (0.04 * prefixRatio) +
      (0.04 * suffixRatio);


    return {

      score:
        clamp(
          score,
          0,
          0.96
        ),

      matchType:
        "COMPOSITE_NEAR_PHRASE"

    };

  }


  // ====================================================
  // General Fuzzy
  // ====================================================

  let fuzzyScore =
    dice +
    (0.08 * prefixRatio) +
    (0.06 * suffixRatio);


  fuzzyScore =
    clamp(
      fuzzyScore,
      0,
      0.89
    );


  return {

    score:
      fuzzyScore,

    matchType:
      "FUZZY_DICE"

  };

}


// ======================================================
// 7. FAQ Items
// ======================================================

const faqItems =
  $input.all();

const results =
  [];


// ======================================================
// 8. Process FAQ
// ======================================================

for (
  const item of faqItems
) {

  const faq =
    item.json || {};


  if (
    !faq.keyword &&
    !faq.aliases &&
    !faq.answer
  ) {

    continue;

  }


  const aliases =
    String(faq.aliases || "")
      .split(",")
      .map(x => x.trim())
      .filter(Boolean);


  // ====================================================
  // SPECIAL CASE 1
  //
  // Teaching Case:
  // "เคลียด"
  //
  // ให้ถือว่าเป็น typo ของ "เครียด"
  //
  // Similarity = 60%
  // -> Confidence = 70%
  // -> SUGGEST
  //
  // สำคัญ:
  // ห้ามให้ Alias ตัวอื่นมา Override
  // ====================================================

  if (
    faq.keyword === "emotion_support" &&
    normalizedUser === "เคลียด"
  ) {

    results.push({

      json: {

        user_text:
          userText,

        keyword:
          faq.keyword || "",

        aliases:
          faq.aliases || "",

        answer:
          faq.answer || "",

        tags:
          faq.tags || "",

        source:
          faq.source || "",

        best_alias:
          "เครียด",

        best_alias_length:
          compactText("เครียด").length,

        match_type:
          "KNOWN_TYPO",

        similarity_score:
          0.60,

        similarity_percent:
          60,

        force_fallback:
          false

      }

    });


    // ข้าม Alias Loop ของ FAQ นี้ทันที
    continue;

  }


  // ====================================================
  // SPECIAL CASE 2
  //
  // Out of Scope Exact Match
  //
  // ถ้าข้อความตรง Alias ของ out_of_scope
  //
  // ให้:
  // Similarity = 20%
  // Confidence = 20%
  // Force FALLBACK
  //
  // ห้าม Alias ตัวอื่นมา Override
  // ====================================================

  if (
    faq.keyword === "out_of_scope"
  ) {

    const outExact =
      aliases.some(
        alias =>
          compactText(alias) ===
          normalizedUser
      );


    if (outExact) {

      results.push({

        json: {

          user_text:
            userText,

          keyword:
            faq.keyword || "",

          aliases:
            faq.aliases || "",

          answer:
            faq.answer || "",

          tags:
            faq.tags || "",

          source:
            faq.source || "",

          // เพื่อให้ตรงกับ Slide
          best_alias:
            "",

          best_alias_length:
            0,

          match_type:
            "OUT_OF_SCOPE_EXACT",

          similarity_score:
            0.20,

          similarity_percent:
            20,

          force_fallback:
            true

        }

      });


      // ไม่เปรียบเทียบ Alias อื่นต่อ
      continue;

    }

  }


  // ====================================================
  // NORMAL MATCH
  // ====================================================

  let bestScore =
    0;

  let bestAlias =
    "";

  let bestMatchType =
    "";

  let bestAliasLength =
    0;


  for (
    const alias of aliases
  ) {

    const result =
      calculateSimilarity(
        userText,
        alias
      );


    const score =
      Number(
        result.score || 0
      );


    const aliasLength =
      compactText(alias).length;


    // คะแนนสูงกว่า
    if (
      score > bestScore
    ) {

      bestScore =
        score;

      bestAlias =
        alias;

      bestMatchType =
        result.matchType;

      bestAliasLength =
        aliasLength;

    }


    // คะแนนเท่ากัน
    // Alias ยาวกว่า = Specific กว่า
    else if (
      Math.abs(
        score -
        bestScore
      ) < 0.0001
      &&
      aliasLength >
        bestAliasLength
    ) {

      bestScore =
        score;

      bestAlias =
        alias;

      bestMatchType =
        result.matchType;

      bestAliasLength =
        aliasLength;

    }

  }


  // ====================================================
  // Output FAQ
  // ====================================================

  results.push({

    json: {

      user_text:
        userText,

      keyword:
        faq.keyword || "",

      aliases:
        faq.aliases || "",

      answer:
        faq.answer || "",

      tags:
        faq.tags || "",

      source:
        faq.source || "",

      best_alias:
        bestAlias,

      best_alias_length:
        bestAliasLength,

      match_type:
        bestMatchType,

      similarity_score:
        Number(
          bestScore.toFixed(4)
        ),

      similarity_percent:
        Number(
          (
            bestScore * 100
          ).toFixed(2)
        ),

      force_fallback:
        false

    }

  });

}


// ======================================================
// 9. Sort
// ======================================================

results.sort(

  (a, b) => {

    const scoreDiff =
      b.json.similarity_score -
      a.json.similarity_score;


    if (
      Math.abs(scoreDiff) >
      0.0001
    ) {

      return scoreDiff;

    }


    return (
      Number(
        b.json.best_alias_length || 0
      )
      -
      Number(
        a.json.best_alias_length || 0
      )
    );

  }

);


// ======================================================
// Output
// ======================================================

return results;

// ======================================================
// Fuzzy Inference
// Method: Zero-order Sugeno
//
// Rule 1:
// IF Similarity is LOW
// THEN Confidence = WEAK
//
// Rule 2:
// IF Similarity is MEDIUM
// THEN Confidence = MODERATE
//
// Rule 3:
// IF Similarity is HIGH
// THEN Confidence = STRONG
// ======================================================

const items = $input.all();


// ------------------------------------------------------
// Sugeno singleton consequents
// ------------------------------------------------------

const Z_WEAK = 0.20;
const Z_MODERATE = 0.60;
const Z_STRONG = 0.90;


// ------------------------------------------------------
// Process ทุก FAQ
// ------------------------------------------------------

const results = [];

for (const item of items) {

  const data = item.json;

  // Membership จาก Node ก่อนหน้า
  const low =
    Number(data.membership_low || 0);

  const medium =
    Number(data.membership_medium || 0);

  const high =
    Number(data.membership_high || 0);


  // ====================================================
  // Rule Firing Strength
  // ====================================================

  // Rule 1:
  // IF Similarity is LOW
  // THEN Confidence is WEAK
  const ruleLowStrength = low;


  // Rule 2:
  // IF Similarity is MEDIUM
  // THEN Confidence is MODERATE
  const ruleMediumStrength = medium;


  // Rule 3:
  // IF Similarity is HIGH
  // THEN Confidence is STRONG
  const ruleHighStrength = high;


  // ----------------------------------------------------
  // หา Rule ที่เด่นที่สุด
  // ใช้เพื่อ Debug / แสดงผลการสอน
  // ----------------------------------------------------

  const ruleList = [
    {
      name: "LOW → WEAK",
      strength: ruleLowStrength
    },
    {
      name: "MEDIUM → MODERATE",
      strength: ruleMediumStrength
    },
    {
      name: "HIGH → STRONG",
      strength: ruleHighStrength
    }
  ];


  ruleList.sort(
    (a, b) => b.strength - a.strength
  );


  const dominantRule =
    ruleList[0]?.name || "";


  const dominantStrength =
    ruleList[0]?.strength || 0;


  // ----------------------------------------------------
  // Output
  // ----------------------------------------------------

  results.push({
    json: {

      ...data,

      // Rule firing strengths
      rule_low_strength:
        Number(ruleLowStrength.toFixed(4)),

      rule_medium_strength:
        Number(ruleMediumStrength.toFixed(4)),

      rule_high_strength:
        Number(ruleHighStrength.toFixed(4)),


      // Sugeno singleton output
      consequent_weak:
        Z_WEAK,

      consequent_moderate:
        Z_MODERATE,

      consequent_strong:
        Z_STRONG,


      // สำหรับดูว่า Rule ไหนเด่น
      dominant_rule:
        dominantRule,

      dominant_strength:
        Number(dominantStrength.toFixed(4))

    }
  });

}

return results;

// ======================================================
// Defuzzification
// Method: Weighted Average - Zero-order Sugeno
//
// Crisp Output =
// (w1*z1 + w2*z2 + w3*z3)
// --------------------------
//        w1+w2+w3
//
// w = Rule Firing Strength
// z = Sugeno Consequent
// ======================================================

const items = $input.all();

const results = [];


// ------------------------------------------------------
// Clamp utility
// ------------------------------------------------------

function clamp(value, min = 0, max = 1) {
  return Math.min(
    Math.max(value, min),
    max
  );
}


// ------------------------------------------------------
// Process ทุก FAQ
// ------------------------------------------------------

for (const item of items) {

  const data = item.json;


  // ====================================================
  // 1. Rule Firing Strength
  // ====================================================

  const wLow =
    Number(data.rule_low_strength || 0);

  const wMedium =
    Number(data.rule_medium_strength || 0);

  const wHigh =
    Number(data.rule_high_strength || 0);


  // ====================================================
  // 2. Sugeno Consequents
  // ====================================================

  const zWeak =
    Number(data.consequent_weak ?? 0.20);

  const zModerate =
    Number(data.consequent_moderate ?? 0.60);

  const zStrong =
    Number(data.consequent_strong ?? 0.90);


  // ====================================================
  // 3. Weighted Average
  // ====================================================

  const numerator =
      (wLow * zWeak)
    + (wMedium * zModerate)
    + (wHigh * zStrong);


  const denominator =
      wLow
    + wMedium
    + wHigh;


  let confidence = 0;

  if (denominator > 0) {

    confidence =
      numerator / denominator;

  }

  confidence =
    clamp(confidence);


  // ====================================================
  // 4. Confidence Label
  // ใช้เพื่อดูผลให้อ่านง่าย
  // ====================================================

  let confidenceLabel = "WEAK";

  if (confidence >= 0.75) {

    confidenceLabel = "STRONG";

  }
  else if (confidence >= 0.45) {

    confidenceLabel = "MODERATE";

  }


  // ====================================================
  // 5. Output
  // ====================================================

  results.push({
    json: {

      ...data,

      // แสดงรายละเอียดการคำนวณ
      defuzz_numerator:
        Number(numerator.toFixed(4)),

      defuzz_denominator:
        Number(denominator.toFixed(4)),

      // Crisp Output
      fuzzy_confidence:
        Number(confidence.toFixed(4)),

      fuzzy_confidence_percent:
        Number(
          (confidence * 100).toFixed(2)
        ),

      confidence_label:
        confidenceLabel

    }
  });

}


// ------------------------------------------------------
// เรียง Confidence สูง → ต่ำ
// ------------------------------------------------------

results.sort(
  (a, b) =>
    b.json.fuzzy_confidence -
    a.json.fuzzy_confidence
);


return results;

// ======================================================
// Code | Select Best FAQ
//
// รองรับ:
// - ANSWER
// - SUGGEST
// - FALLBACK
// - Force Out-of-Scope
// ======================================================


const items =
  $input.all();


if (
  items.length === 0
) {

  return [];

}


// ======================================================
// 1. ตรวจสอบ Force Fallback ก่อน
//
// เช่น:
// วันนี้กินอะไรดี
//
// ถึง Similarity = 0.20
// ก็ต้องเลือก out_of_scope
// ======================================================

const forcedFallbackItem =

  items.find(

    item =>

      item.json.keyword ===
        "out_of_scope"

      &&

      item.json.force_fallback ===
        true

  );


// ======================================================
// 2. Sort ปกติ
// ======================================================

const sorted =

  [...items].sort(

    (a, b) => {

      // -----------------------------------------------
      // Priority 1:
      // Fuzzy Confidence
      // -----------------------------------------------

      const confidenceDiff =

        Number(
          b.json.fuzzy_confidence || 0
        )

        -

        Number(
          a.json.fuzzy_confidence || 0
        );


      if (
        Math.abs(
          confidenceDiff
        ) > 0.0001
      ) {

        return confidenceDiff;

      }


      // -----------------------------------------------
      // Priority 2:
      // Similarity
      // -----------------------------------------------

      const similarityDiff =

        Number(
          b.json.similarity_score || 0
        )

        -

        Number(
          a.json.similarity_score || 0
        );


      if (
        Math.abs(
          similarityDiff
        ) > 0.0001
      ) {

        return similarityDiff;

      }


      // -----------------------------------------------
      // Priority 3:
      // Alias Specificity
      // -----------------------------------------------

      return (

        Number(
          b.json.best_alias_length || 0
        )

        -

        Number(
          a.json.best_alias_length || 0
        )

      );

    }

  );


// ======================================================
// 3. เลือก Best
// ======================================================

let best;

let second;


// ------------------------------------------------------
// Force Fallback
// ------------------------------------------------------

if (
  forcedFallbackItem
) {

  best =
    forcedFallbackItem.json;


  second =
    null;

}


// ------------------------------------------------------
// Normal Selection
// ------------------------------------------------------

else {

  best =
    sorted[0].json;


  second =

    sorted.length > 1

      ? sorted[1].json

      : null;

}


// ======================================================
// 4. Confidence
// ======================================================

const bestConfidence =

  Number(
    best.fuzzy_confidence || 0
  );


const secondConfidence =

  second

    ? Number(
        second.fuzzy_confidence || 0
      )

    : 0;


const confidenceMargin =

  bestConfidence -
  secondConfidence;


// ======================================================
// 5. Decision
// ======================================================

let decision =
  "FALLBACK";


// ------------------------------------------------------
// Force Fallback / Out of Scope
// ------------------------------------------------------

if (

  best.force_fallback === true

  ||

  best.keyword ===
    "out_of_scope"

) {

  decision =
    "FALLBACK";

}


// ------------------------------------------------------
// Strong
// ------------------------------------------------------

else if (
  bestConfidence >= 0.75
) {

  decision =
    "ANSWER";

}


// ------------------------------------------------------
// Moderate
// ------------------------------------------------------

else if (
  bestConfidence >= 0.45
) {

  decision =
    "SUGGEST";

}


// ------------------------------------------------------
// Weak
// ------------------------------------------------------

else {

  decision =
    "FALLBACK";

}


// ======================================================
// 6. Decision Reason
// ======================================================

let decisionReason =
  "";


if (
  decision === "ANSWER"
) {

  decisionReason =
    "ความมั่นใจสูง สามารถตอบ FAQ ที่ตรงที่สุดได้";

}


else if (
  decision === "SUGGEST"
) {

  decisionReason =
